OY(a){return"\u0625\u0639\u0627\u062f\u0629 \u062a\u0639\u064a\u064a\u0646 \u0631\u0645\u0632 "+a+"\u061f"},
gOX(){return"\u0633\u064a\u064f\u0637\u0644\u0628 \u0645\u0646\u0647\u0645 \u062a\u0639\u064a\u064a\u0646 \u0631\u0645\u0632 \u062c\u062f\u064a\u062f \u062a\u0645\u0627\u0645\u064b\u0627 \u0641\u064a \u0627\u0644\u0645\u0631\u0629 \u0627\u0644\u0642\u0627\u062f\u0645\u0629 \u0627\u0644\u062a\u064a \u064a\u0633\u062c\u0644\u0648\u0646 \u0641\u064a\u0647\u0627 \u0627\u0644\u062f\u062e\u0648\u0644. \u064a\u062a\u0648\u0642\u0641 \u0631\u0645\u0632\u0647\u0645 \u0627\u0644\u062d\u0627\u0644\u064a \u0639\u0646 \u0627\u0644\u0639\u0645\u0644 \u0641\u0648\u0631\u064b\u0627."},
